import { buscarTrayectoRepository, buscarConductorRepository, asignarConductorRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarConductorService(trayectoId, conductorId, rol) {
  const trayecto = await buscarTrayectoRepository(trayectoId);
  const conductor = await buscarConductorRepository(conductorId);
  if (!trayecto || !conductor) {
    throw new ReferenciaInexistenteError('No existe el trayecto o el conductor');
  }
  return asignarConductorRepository(trayectoId, conductorId, rol);
}

import { asignarConductorService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const trayectoId = Number(event.pathParameters.trayectoId);
  const { conductorId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarConductorService(trayectoId, conductorId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El conductor ya está asignado a ese trayecto' }) };
    }
    throw error;
  }
}

